<?php $editando = is_array($editar ?? null); ?>
<section class="page-head"><div><span class="badge">Cadastro</span><h1>Escolas</h1><p>Cadastre as unidades escolares que receberão materiais do almoxarifado.</p></div><a class="button secondary" href="?route=/dashboard">Voltar ao painel</a></section>
<?php if (!empty($flash)): ?><div class="alert <?= ($flash['tipo'] ?? '') === 'sucesso' ? 'success' : 'error' ?>"><?= htmlspecialchars((string) ($flash['mensagem'] ?? ''), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<section class="crud-layout"><article class="card form-card"><h2><?= $editando ? 'Editar escola' : 'Nova escola' ?></h2><form method="post" action="?route=/escolas/salvar"><input type="hidden" name="id" value="<?= (int) ($editar['id'] ?? 0) ?>"><label for="nome">Nome da escola</label><input id="nome" name="nome" maxlength="180" required value="<?= htmlspecialchars((string) ($editar['nome'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><label for="codigo">Código <span class="optional">(opcional)</span></label><input id="codigo" name="codigo" maxlength="50" value="<?= htmlspecialchars((string) ($editar['codigo'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"><div class="form-actions"><button class="button" type="submit"><?= $editando ? 'Salvar alterações' : 'Cadastrar escola' ?></button><?php if ($editando): ?><a class="button ghost" href="?route=/escolas">Cancelar</a><?php endif; ?></div></form></article>
<article class="card list-card"><div class="list-title"><h2>Escolas cadastradas</h2><span><?= count($escolas) ?> registro(s)</span></div><?php if (!$escolas): ?><p class="empty-state">Nenhuma escola cadastrada.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Escola</th><th>Código</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($escolas as $escola): ?><tr><td><strong><?= htmlspecialchars($escola['nome'], ENT_QUOTES, 'UTF-8') ?></strong></td><td><?= htmlspecialchars((string) ($escola['codigo'] ?: '—'), ENT_QUOTES, 'UTF-8') ?></td><td><span class="pill <?= $escola['ativo'] ? 'active' : 'inactive' ?>"><?= $escola['ativo'] ? 'Ativa' : 'Inativa' ?></span></td><td class="actions-cell"><a class="text-link" href="?route=/escolas&id=<?= (int) $escola['id'] ?>">Editar</a><form method="post" action="?route=/escolas/status"><input type="hidden" name="id" value="<?= (int) $escola['id'] ?>"><input type="hidden" name="ativo" value="<?= $escola['ativo'] ? 0 : 1 ?>"><button class="link-button <?= $escola['ativo'] ? 'danger-text' : '' ?>" type="submit"><?= $escola['ativo'] ? 'Desativar' : 'Ativar' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></article></section>
